git('add','--',str(DEST.relative_to(ROOT)),str(report_path.relative_to(ROOT)),str(life.relative_to(ROOT)))
git('diff','--cached','--check')
git('commit','-m','Preserve Live8 configuration diagnostic failure and verified secret removal')
head=git('rev-parse','HEAD').decode().strip()
assert git('status','--porcelain')==b''
for path,digest in verification['product_trees'].items():assert git('rev-parse','HEAD:'+path).decode().strip()==digest
for item in files:assert sha(git('show',head+':'+str(DEST.relative_to(ROOT)).replace('\\','/')+'/'+item['path']))==item['sha256']
print(json.dumps({'status':'PASS','head':head,'packet_payloads':len(files),'packet_index_sha256':sha((DEST/'FILE_INDEX.json').read_bytes()),'original_payloads_preserved':36,'application_source':publication['application_source'],'source_review_sha256':publication['root_source_review_sha256'],'report_sha256':sha(report_path.read_bytes()),'secret_cleanup_required':False,'new_tests':0,'new_downloads':0}))
